"""Рядок 152, річ з фото. (1) 30 речей вибірки жнив v2 різних слотів як «її фото»: ΔE00 виміру проти
запису каталогу, збіг слова-вікна, «у палітрі» профілю стенда проти членства за записом каталогу.
(2) 10 закріплених речей × 3 сценарії, неслухняна модель руки 1: частка образів із річчю (має бути
100 %) і образів із другою річчю в її слоті (має бути 0). Запуск із `джерела`: python3 проби/foto_rechi_152.py"""
import json, base64, statistics as st, sys, itertools; sys.path.insert(0, '.'); from PIL import Image
import colorspace as cs, palettes as ПЛ, bridge as B, річ_з_фото as Р; from міст_вхід import _збірка, _нормалізувати_вхід
В = [р for р in json.load(open('аудит/збагачення_v2_вибірка.json', encoding='utf-8'))['речі']
     if р.get('фото_показу') and (р.get('запис') or {}).get('колір_основний') and р['слот'] in Р.СЛОТИ_РЕЧІ]
ряди = [list(г) for _, г in itertools.groupby(sorted(В, key=lambda р: р['слот']), key=lambda р: р['слот'])]
вибір = [р for ряд in itertools.zip_longest(*ряди) for р in ряд if р][:30]
def пікселі(шлях):
    і = Image.open(шлях).convert('RGB'); і.thumbnail((Р.МАКС_СТОРОНА, Р.МАКС_СТОРОНА))
    return dict(дані=base64.urlsafe_b64encode(і.tobytes()).decode(), ширина=і.width, висота=і.height)
вх = json.load(open('стенд_вх.json')); П = ПЛ.палітра_практична(_збірка(_нормалізувати_вхід(dict(вх)))[0])
ΔE, слово, стан, речі = [], [], [], []
for р in вибір:
    к = р['запис']['колір_основний']; в = Р.виміряти(пікселі('аудит/' + р['фото_показу']), слово_моделі=к['слово'])
    if not в.get('lab'): continue
    ΔE.append(cs.de00(tuple(в['lab']), cs.hx(к['hex']))); слово.append(в['слово'] == к['слово'])
    у = lambda lab: Р.членство_в_палітрі(lab, П)['стан'] == 'у палітрі'
    стан.append((у(в['lab']), у(cs.hx(к['hex'])))); речі.append((р, в))
q = sorted(ΔE); print('виміряно %d із %d · ΔE00 виміру проти запису каталогу: медіана %.1f, p90 %.1f' % (len(q), len(вибір), st.median(q), q[int(0.9 * (len(q) - 1))]))
print('слово-вікно збіглось: %d/%d (%.0f %%)' % (sum(слово), len(слово), 100 * sum(слово) / len(слово)))
print('«у палітрі» (профіль стенд_вх): за виміром %d, за записом %d, вердикт збігся %d/%d' % (sum(a for a, _ in стан), sum(b for _, b in стан), sum(a == b for a, b in стан), len(стан)))
СЦЕНАРІЇ = [dict(нагода='робота', місце='офіс_корпоративний', година=10, темп_c=18),
            dict(нагода='побачення', місце='ресторан_районний', година=19, темп_c=14),
            dict(нагода='щоденне', місце='парк', година=15, темп_c=5, опади='дощ')]
закр = [x for ряд in itertools.zip_longest(*[[x for x in речі if x[0]['слот'] == с] for с in ('сукня', 'верх', 'низ', 'верхній_шар', 'взуття', 'сумка', 'шарф')]) for x in ряд if x][:10]
з_річчю = всього = друга = 0
for (р, в), сц in itertools.product(закр, СЦЕНАРІЇ):
    п = р['поля']; річ = dict(ід='ф1', фото='ф1', назва=р['назва'][:40], слот=р['слот'], колір=в['слово'], крій=п.get('крій'), довжина=п.get('довжина'),
                           ошатність=п.get('формальність'), чия='моя', закріплена=True, вимір=dict(lab=в['lab'], hex=в['hex'], слово=в['слово']))
    д = dict(вх, сценарій=сц, паспорт=dict(сц, речі_з_фото=[річ]), варіантів=10, бюджет_символів=120000, без_фото=1)
    пул = json.loads(json.loads(B.виклик('запити', json.dumps(д, ensure_ascii=False)))['руки']['1'])['пул']
    н = lambda с, i: пул[с][i % len(пул[с])]['н'] if пул.get(с) else None
    обр = [dict(ід='о%d' % i, речі=[x for x in [н('верх', i), н('низ', i), н('взуття', i), н('сумка', i), н('шарф', i) or н('сережки', i)] if x]) for i in range(1, 5)]
    for о in json.loads(B.виклик('від_моделі', json.dumps(dict(д, текст_моделі=json.dumps(dict(версія='1', образи=обр), ensure_ascii=False)), ensure_ascii=False))).get('образи') or []:
        всього += 1; з_річчю += 'її-ф1' in о['ід']; друга += sum(с in Р.займає(р['слот']) for с in (о.get('слоти_н') or {}).values()) > 1
print('закріплено %d речей × %d сценарії: образів руки 1 %d, з її річчю %d (%.0f %%), з другою річчю в її слоті %d' % (len(закр), len(СЦЕНАРІЇ), всього, з_річчю, 100 * з_річчю / max(1, всього), друга))
